/**
 * The real drag layer against REAL dnd-kit sensors (MouseSensor, TouchSensor) in jsdom.
 * This is the one suite that loads `@dnd-kit/core`. Page and component suites mock the
 * loader with `test-utils/fakeDragLayer`.
 *
 * jsdom has no layout, so geometry comes from `stubRects`. The rects are generated by
 * `gridFlow` for the order the harness renders, so they are grid-consistent; the planner's
 * stability vetting predicts the same flow. Cells register through the real `dragBridge`,
 * exactly like the page's `WidgetCell`: the drag surface and the Move button forward
 * `onMouseDown` / `onTouchStart` to `bridge.start`.
 *
 * What is pinned here: the activation thresholds, the reorder gates (rect re-measure and
 * hysteresis), the drift re-measure, cancel paths (including a release dnd-kit drops before
 * its start commits), the resize guard, dnd-kit's click suppression, the zone filter,
 * `enabled`, the touch long-press, the silenced dnd-kit live region (and no dnd-kit
 * attributes on the REAL `WidgetCell`), the portaled ghost, and the drop animation.
 */
import React, { useCallback, useRef, useState } from 'react';
import { MemoryRouter } from 'react-router-dom';
import { act, fireEvent, render, screen } from '@testing-library/react';
import DashboardDragLayer, {
  DRAG_OVERLAY_Z_INDEX,
  DROP_ANIMATION_EASING,
  DROP_ANIMATION_MS,
} from './DashboardDragLayer';
import { createDragBridge, type DragBridge } from './dragBridge';
import { loadDashboardDragLayer } from './loadDragLayer';
import type { DragWidgetDescription } from './dragLayerTypes';
import type { EditableZone } from '../dashboardLayout';
import type { DashboardWidgetComponent, PanelSize } from '../widgetTypes';
import { WidgetCell, type WidgetCellEditor } from '../WidgetCell';
import { WIDGETS_BY_ID } from '../widgetRegistry';
import { flowGrid } from '../../../test-utils/gridFlow';
import {
  installFakeAnimate,
  mouseDown,
  mouseMove,
  mouseUp,
  stubRects,
  touchEnd,
  touchMove,
  touchStart,
  type FakeAnimate,
  type Point,
  type RectInit,
  type RectStub,
} from '../../../test-utils/dndDom';

// The real WidgetCell (integration test below) reaches the widget ErrorBoundary.
jest.mock('../../../services/api', () => ({ __esModule: true, default: {} }));
jest.mock('../../../services/errorLogging', () => ({ logError: jest.fn() }));

// ── Geometry ─────────────────────────────────────────────────────────────────

interface Orders {
  kpi: readonly string[];
  panel: readonly string[];
}

type PanelSizes = Readonly<Record<string, PanelSize>>;

const INITIAL: Orders = { kpi: ['K1', 'K2', 'K3'], panel: ['A', 'B', 'C'] };
/** xl, 1200 px wide: [A half | B half] / [C full]. */
const HALVES: PanelSizes = { A: 'half', B: 'half', C: 'full' };
/** [A third | B third | hole] / [C full]: the hole is a zone hit. */
const THIRDS: PanelSizes = { A: 'third', B: 'third', C: 'full' };
const PANEL_HEIGHTS: Readonly<Record<string, number>> = { A: 200, B: 200, C: 150 };
const GRID_WIDTH = 1200;
const KPI_TOP = 170;
const PANEL_TOP = 270;
const DEFAULT_VIEWPORT_WIDTH = 1024;

/** Moves every rect `layoutRects` produces (content appearing above both zones, or a scroll). */
let geometryShiftY = 0;

/** Cell and zone rects for an order, keyed the way `stubRects` reads them. */
function layoutRects(orders: Orders, sizes: PanelSizes): Map<string, RectInit> {
  const rects = new Map<string, RectInit>();
  const kpi = flowGrid(
    orders.kpi.map(id => ({ id, height: 72 })),
    { kpiColumns: 5 },
    { top: KPI_TOP, width: GRID_WIDTH }
  );
  const panel = flowGrid(
    orders.panel.map(id => ({ id, size: sizes[id], height: PANEL_HEIGHTS[id] })),
    'xl',
    { top: PANEL_TOP, width: GRID_WIDTH }
  );
  kpi.rects.forEach((rect, id) => rects.set(id, rect));
  panel.rects.forEach((rect, id) => rects.set(id, rect));
  rects.set('zone-kpi', kpi.zoneRect);
  rects.set('zone-panel', panel.zoneRect);
  if (geometryShiftY !== 0) rects.forEach((rect, key) => rects.set(key, { ...rect, top: rect.top + geometryShiftY }));
  return rects;
}

// With HALVES: A is x 0–592, B is x 608–1200 (midline 904), both y 270–470; C is the full
// row at y 486–636 (midline 561). The KPI tiles are 233.6 px wide at y 170–242.
const A_CENTER: Point = { x: 296, y: 370 };
const A_LIFTED: Point = { x: 303, y: 370 };
const B_RIGHT: Point = { x: 1000, y: 370 };
const C_LOWER: Point = { x: 600, y: 600 };
const K1_CENTER: Point = { x: 116, y: 206 };
const K1_LIFTED: Point = { x: 123, y: 206 };
const K3_RIGHT: Point = { x: 660, y: 206 };

const TITLES: Readonly<Record<string, string>> = {
  A: 'Work Center Status',
  B: 'Capacity Overview',
  C: 'Live Shop Activity',
  K1: 'Overdue',
  K2: 'Due Today',
  K3: 'In Progress',
};

function describeWidget(id: string): DragWidgetDescription {
  return { title: TITLES[id] ?? id, sizeLabel: id.startsWith('K') ? 'Key metric' : 'Half' };
}

// ── Harness ──────────────────────────────────────────────────────────────────

interface Spies {
  onDragStart: jest.Mock<void, [EditableZone, string]>;
  onReorder: jest.Mock<void, [EditableZone, readonly string[]]>;
  onDragEnd: jest.Mock<void, [EditableZone, string]>;
  onDragCancel: jest.Mock<void, [EditableZone, string]>;
  onMoveClick: jest.Mock<void, [string]>;
}

function createSpies(): Spies {
  return {
    onDragStart: jest.fn<void, [EditableZone, string]>(),
    onReorder: jest.fn<void, [EditableZone, readonly string[]]>(),
    onDragEnd: jest.fn<void, [EditableZone, string]>(),
    onDragCancel: jest.fn<void, [EditableZone, string]>(),
    onMoveClick: jest.fn<void, [string]>(),
  };
}

interface HarnessProps {
  bridge: DragBridge;
  spies: Spies;
  initial: Orders;
  enabled: boolean;
  reducedMotion: boolean;
  /** Render each live order the layer asks for (the page does). Off: the order never changes. */
  apply: boolean;
  /** Mount the layer (the page mounts it only in edit mode). */
  layer: boolean;
  /** Put both zones in an `overflow: auto` container (dnd-kit then tracks its scroll offset). */
  scroller: boolean;
  /** Called with the new orders before they render (re-stubs the rects). */
  onApplied: (orders: Orders) => void;
}

/** A page cell, as `WidgetCell` wires it: a Move button and an aria-hidden drag surface, both forwarding to the bridge. */
function HarnessCell({
  id,
  zone,
  bridge,
  onMoveClick,
}: {
  id: string;
  zone: EditableZone;
  bridge: DragBridge;
  onMoveClick: (id: string) => void;
}) {
  const forward = (event: React.MouseEvent<Element> | React.TouchEvent<Element>) => {
    bridge.start(id, event);
  };
  return (
    <div data-widget-cell={id} ref={bridge.cellRef(id, zone)}>
      <button type="button" onMouseDown={forward} onTouchStart={forward} onClick={() => onMoveClick(id)}>
        Move {id}
      </button>
      <div aria-hidden="true" data-testid={`surface-${id}`} onMouseDown={forward} onTouchStart={forward} />
    </div>
  );
}

function Harness({ bridge, spies, initial, enabled, reducedMotion, apply, layer, scroller, onApplied }: HarnessProps) {
  const [orders, setOrders] = useState<Orders>(initial);
  const rendered = useRef<Orders>(initial);
  const onReorder = useCallback(
    (zone: EditableZone, next: readonly string[]) => {
      spies.onReorder(zone, next);
      if (!apply) return;
      const updated: Orders =
        zone === 'kpi' ? { ...rendered.current, kpi: [...next] } : { ...rendered.current, panel: [...next] };
      rendered.current = updated;
      onApplied(updated);
      setOrders(updated);
    },
    [apply, onApplied, spies]
  );
  const cells = (zone: EditableZone) =>
    orders[zone].map(id => (
      <HarnessCell key={id} id={id} zone={zone} bridge={bridge} onMoveClick={spies.onMoveClick} />
    ));
  return (
    <>
      <div data-testid="scroller" style={scroller ? { overflow: 'auto' } : undefined}>
        <div data-testid="zone-kpi" ref={bridge.zoneRef('kpi')}>
          {cells('kpi')}
        </div>
        <div data-testid="zone-panel" ref={bridge.zoneRef('panel')}>
          {cells('panel')}
        </div>
      </div>
      {layer && (
        <DashboardDragLayer
          bridge={bridge}
          enabled={enabled}
          orders={orders}
          layoutKey={JSON.stringify(orders)}
          reducedMotion={reducedMotion}
          describe={describeWidget}
          onDragStart={spies.onDragStart}
          onReorder={onReorder}
          onDragEnd={spies.onDragEnd}
          onDragCancel={spies.onDragCancel}
        />
      )}
    </>
  );
}

interface RenderOptions {
  enabled?: boolean;
  reducedMotion?: boolean;
  apply?: boolean;
  /** Re-stub the rects for each applied order (default). Off: the stubs keep the old geometry. */
  restub?: boolean;
  sizes?: PanelSizes;
  scroller?: boolean;
}

let stub: RectStub;
let fakeTimers = false;
let animate: FakeAnimate | null = null;

function renderLayer({
  enabled = true,
  reducedMotion = true,
  apply = false,
  restub = true,
  sizes = HALVES,
  scroller = false,
}: RenderOptions = {}) {
  const bridge = createDragBridge();
  const spies = createSpies();
  stub.setAll(layoutRects(INITIAL, sizes));
  const onApplied = (orders: Orders) => {
    if (restub) stub.setAll(layoutRects(orders, sizes));
  };
  const props: HarnessProps = {
    bridge,
    spies,
    initial: INITIAL,
    enabled,
    reducedMotion,
    apply,
    layer: true,
    scroller,
    onApplied,
  };
  const utils = render(<Harness {...props} />);
  return {
    bridge,
    spies,
    container: utils.container,
    rerender: (next: Partial<HarnessProps>) => utils.rerender(<Harness {...props} {...next} />),
    surface: (id: string) => screen.getByTestId(`surface-${id}`),
    moveButton: (id: string) => screen.getByRole('button', { name: `Move ${id}` }),
  };
}

/** Lift a widget with the mouse: press, then move 7 px (past the 6 px threshold). */
function lift(target: Element, from: Point, to: Point) {
  mouseDown(target, from);
  mouseMove(to);
}

/** Lets the overlay settle after a drop or cancel (its exit runs on a resolved promise). */
async function settleOverlay() {
  await act(async () => {
    await Promise.resolve();
  });
}

async function drop(at: Point) {
  mouseUp(at);
  await settleOverlay();
}

function setViewportWidth(width: number) {
  Object.defineProperty(window, 'innerWidth', { configurable: true, writable: true, value: width });
}

function resizeWindow(width: number) {
  setViewportWidth(width);
  act(() => {
    window.dispatchEvent(new Event('resize'));
  });
}

/**
 * jsdom computes no transform matrix, and dnd-kit's drop animation starts only from one:
 * the overlay wrapper (the only element at z-index 55) reports `matrix(1, 0, 0, 1, 40, 50)`.
 * Every other element keeps jsdom's computed style. Restored by `jest.restoreAllMocks()`.
 */
function giveOverlayATransformMatrix() {
  const realGetComputedStyle = window.getComputedStyle.bind(window);
  jest.spyOn(window, 'getComputedStyle').mockImplementation((element, pseudo) => {
    const style = realGetComputedStyle(element, pseudo);
    if (!(element instanceof HTMLElement) || element.style.zIndex !== String(DRAG_OVERLAY_Z_INDEX)) return style;
    return new Proxy(style, {
      get: (target, property) =>
        property === 'transform' ? 'matrix(1, 0, 0, 1, 40, 50)' : Reflect.get(target, property, target),
    });
  });
}

function installFakeTimers() {
  jest.useFakeTimers();
  fakeTimers = true;
}

beforeEach(() => {
  stub = stubRects();
  geometryShiftY = 0;
});

afterEach(async () => {
  stub.restore();
  setViewportWidth(DEFAULT_VIEWPORT_WIDTH);
  animate?.restore();
  animate = null;
  jest.restoreAllMocks();
  if (fakeTimers) {
    // dnd-kit removes a finished drag's document listeners (the click-suppression one
    // included) 50 ms after the release; run that before leaving fake time.
    act(() => {
      jest.runOnlyPendingTimers();
    });
    jest.useRealTimers();
    fakeTimers = false;
  } else {
    await new Promise(resolve => setTimeout(resolve, 60));
  }
});

// ── Tests ────────────────────────────────────────────────────────────────────

describe('DashboardDragLayer (real dnd-kit sensors)', () => {
  it('lifts only past the 6 px mouse threshold', async () => {
    const { spies, surface } = renderLayer();

    // dnd-kit lifts only strictly PAST the distance: 6 px exactly is still a press, 7 px
    // (A_LIFTED) is a drag. The pair pins the threshold at 6 from both sides.
    mouseDown(surface('A'), A_CENTER);
    mouseMove({ x: A_CENTER.x + 6, y: A_CENTER.y });
    expect(spies.onDragStart).not.toHaveBeenCalled();

    mouseMove(A_LIFTED);
    expect(spies.onDragStart).toHaveBeenCalledTimes(1);
    expect(spies.onDragStart).toHaveBeenCalledWith('panel', 'A');

    await drop(A_LIFTED);
    expect(spies.onDragEnd).toHaveBeenCalledWith('panel', 'A');
    expect(spies.onReorder).not.toHaveBeenCalled();
    expect(spies.onDragCancel).not.toHaveBeenCalled();
  });

  it('a press released inside the threshold is no drag, and the click still reaches the Move button', () => {
    const { spies, moveButton } = renderLayer();
    mouseDown(moveButton('A'), A_CENTER);
    mouseMove({ x: A_CENTER.x + 6, y: A_CENTER.y });
    mouseUp({ x: A_CENTER.x + 6, y: A_CENTER.y });
    fireEvent.click(moveButton('A'));

    expect(spies.onDragStart).not.toHaveBeenCalled();
    expect(spies.onDragEnd).not.toHaveBeenCalled();
    expect(spies.onMoveClick).toHaveBeenCalledWith('A');
  });

  it('reorders once over a neighbour, then the rect gate holds however far the pointer moves', async () => {
    // The harness never renders the new order, so the droppables are never re-measured.
    const { spies, surface } = renderLayer({ apply: false });
    lift(surface('A'), A_CENTER, A_LIFTED);

    mouseMove(B_RIGHT);
    expect(spies.onReorder).toHaveBeenCalledTimes(1);
    expect(spies.onReorder).toHaveBeenLastCalledWith('panel', ['B', 'A', 'C']);

    // Every move is ≥ 8 px from the last and still over B's right half (the same target).
    for (let index = 0; index < 20; index += 1) {
      mouseMove({ x: B_RIGHT.x + (index % 2 === 0 ? 10 : -10), y: B_RIGHT.y });
    }
    expect(spies.onReorder).toHaveBeenCalledTimes(1);

    await drop(B_RIGHT);
    expect(spies.onDragEnd).toHaveBeenCalledWith('panel', 'A');
  });

  it('a stationary pointer stays put after the layout reflows: 20 small moves change nothing', async () => {
    const { spies, surface } = renderLayer({ apply: true });
    lift(surface('A'), A_CENTER, A_LIFTED);
    mouseMove(B_RIGHT);
    expect(spies.onReorder).toHaveBeenCalledTimes(1);

    for (let index = 0; index < 20; index += 1) {
      mouseMove({ x: B_RIGHT.x + (index % 3) - 1, y: B_RIGHT.y + (index % 2) });
    }
    expect(spies.onReorder).toHaveBeenCalledTimes(1);
    await drop(B_RIGHT);
  });

  it('holds a reorder until the pointer has moved 8 px since the last one', async () => {
    // The order renders (so the droppables are re-measured) but the stubs keep the old
    // geometry, so a few px left of B's midline would flip the order straight back.
    const { spies, surface } = renderLayer({ apply: true, restub: false });
    lift(surface('A'), A_CENTER, A_LIFTED);

    mouseMove({ x: 910, y: 370 }); // just right of B's midline (904)
    expect(spies.onReorder).toHaveBeenCalledTimes(1);
    expect(spies.onReorder).toHaveBeenLastCalledWith('panel', ['B', 'A', 'C']);

    mouseMove({ x: 903, y: 370 }); // left of the midline, 7 px away: held
    expect(spies.onReorder).toHaveBeenCalledTimes(1);

    mouseMove({ x: 901, y: 370 }); // 9 px away: allowed
    expect(spies.onReorder).toHaveBeenCalledTimes(2);
    expect(spies.onReorder).toHaveBeenLastCalledWith('panel', ['A', 'B', 'C']);
    await drop({ x: 901, y: 370 });
  });

  it('re-measures after the new layout commits, which reopens the gate for the next target', async () => {
    const { spies, surface } = renderLayer({ apply: true });
    lift(surface('A'), A_CENTER, A_LIFTED);
    mouseMove(B_RIGHT);
    expect(spies.onReorder).toHaveBeenLastCalledWith('panel', ['B', 'A', 'C']);

    // Now [B | A] / [C]: the lower half of the full-width C means "after C".
    mouseMove(C_LOWER);
    expect(spies.onReorder).toHaveBeenCalledTimes(2);
    expect(spies.onReorder).toHaveBeenLastCalledWith('panel', ['B', 'C', 'A']);

    await drop(C_LOWER);
    expect(spies.onDragEnd).toHaveBeenCalledWith('panel', 'A');
  });

  it('a pointer in a row-end hole lands the widget after the last widget on that row (zone hit)', async () => {
    const { spies, surface } = renderLayer({ apply: true, sizes: THIRDS });
    lift(surface('A'), { x: 190, y: 370 }, { x: 197, y: 370 });

    mouseMove({ x: 1000, y: 370 }); // right of B (x 405–795): no cell, inside the panel grid
    expect(spies.onReorder).toHaveBeenCalledTimes(1);
    expect(spies.onReorder).toHaveBeenLastCalledWith('panel', ['B', 'A', 'C']);
    await drop({ x: 1000, y: 370 });
  });

  it('Escape cancels the drag', async () => {
    const { spies, surface } = renderLayer({ apply: true });
    lift(surface('A'), A_CENTER, A_LIFTED);
    mouseMove(B_RIGHT);

    fireEvent.keyDown(document, { key: 'Escape', code: 'Escape' });
    await settleOverlay();
    expect(spies.onDragCancel).toHaveBeenCalledTimes(1);
    expect(spies.onDragCancel).toHaveBeenCalledWith('panel', 'A');

    mouseUp(B_RIGHT);
    expect(spies.onDragEnd).not.toHaveBeenCalled();
  });

  it('a resize within the breakpoint keeps the drag, swallows the event and re-measures', async () => {
    const { spies, surface } = renderLayer({ apply: false });
    const pageListener = jest.fn();
    window.addEventListener('resize', pageListener);
    try {
      lift(surface('A'), A_CENTER, A_LIFTED);
      mouseMove(B_RIGHT);
      mouseMove({ x: B_RIGHT.x + 10, y: B_RIGHT.y });
      expect(spies.onReorder).toHaveBeenCalledTimes(1); // gate 1: nothing re-measured yet

      resizeWindow(1100); // still lg (1024–1279), e.g. the iOS toolbar collapsing
      expect(spies.onDragCancel).not.toHaveBeenCalled();
      expect(pageListener).not.toHaveBeenCalled();

      // The guard re-measured, so the gate is open again.
      mouseMove({ x: B_RIGHT.x + 20, y: B_RIGHT.y });
      expect(spies.onReorder).toHaveBeenCalledTimes(2);

      await drop({ x: B_RIGHT.x + 20, y: B_RIGHT.y });
      expect(spies.onDragEnd).toHaveBeenCalledWith('panel', 'A');

      // No drag: a resize passes through untouched.
      resizeWindow(1110);
      expect(pageListener).toHaveBeenCalledTimes(1);
    } finally {
      window.removeEventListener('resize', pageListener);
    }
  });

  it('a resize across a breakpoint cancels the drag', async () => {
    const { spies, surface } = renderLayer({ apply: true });
    lift(surface('A'), A_CENTER, A_LIFTED);
    mouseMove(B_RIGHT);

    resizeWindow(1300); // lg → xl
    await settleOverlay();
    expect(spies.onDragCancel).toHaveBeenCalledWith('panel', 'A');
    mouseUp(B_RIGHT);
    expect(spies.onDragEnd).not.toHaveBeenCalled();
  });

  it('the click that follows a real drag never reaches the Move button', async () => {
    const { spies, moveButton } = renderLayer({ apply: true });
    fireEvent.click(moveButton('A'));
    expect(spies.onMoveClick).toHaveBeenCalledTimes(1);

    lift(moveButton('A'), A_CENTER, A_LIFTED);
    mouseMove(B_RIGHT);
    await drop(B_RIGHT);
    fireEvent.click(moveButton('A'));
    expect(spies.onMoveClick).toHaveBeenCalledTimes(1);

    // dnd-kit lifts the suppression shortly after the drop.
    await act(async () => {
      await new Promise(resolve => setTimeout(resolve, 60));
    });
    fireEvent.click(moveButton('A'));
    expect(spies.onMoveClick).toHaveBeenCalledTimes(2);
  });

  it('a KPI drag ignores the panel droppables and reorders only within the strip', async () => {
    const { spies, surface } = renderLayer({ apply: true });
    lift(surface('K1'), K1_CENTER, K1_LIFTED);
    expect(spies.onDragStart).toHaveBeenCalledWith('kpi', 'K1');

    mouseMove(B_RIGHT); // over a panel
    mouseMove({ x: 600, y: 478 }); // the panel grid's row gutter
    mouseMove(C_LOWER);
    expect(spies.onReorder).not.toHaveBeenCalled();

    mouseMove(K3_RIGHT);
    expect(spies.onReorder).toHaveBeenCalledTimes(1);
    expect(spies.onReorder).toHaveBeenLastCalledWith('kpi', ['K2', 'K3', 'K1']);

    await drop(K3_RIGHT);
    expect(spies.onDragEnd).toHaveBeenCalledWith('kpi', 'K1');
  });

  it('a KPI drag treats panel cells as empty strip space even where the zones overlap (zone filter)', async () => {
    const { spies, surface } = renderLayer({ apply: true });
    // Stretch the KPI strip's grid over the panels: B now lies inside the strip's rect, but
    // it is not a KPI droppable, so the pointer over it is a zone hit in the strip's one
    // row band — after the last tile left of the pointer (K3).
    stub.set('zone-kpi', { left: 0, top: KPI_TOP, width: GRID_WIDTH, height: 500 });
    lift(surface('K1'), K1_CENTER, K1_LIFTED);

    mouseMove(B_RIGHT);
    expect(spies.onReorder).toHaveBeenCalledTimes(1);
    expect(spies.onReorder).toHaveBeenLastCalledWith('kpi', ['K2', 'K3', 'K1']);
    await drop(B_RIGHT);
    expect(spies.onDragEnd).toHaveBeenCalledWith('kpi', 'K1');
  });

  it('counts scrolling as travel: a scroll under a still pointer can move the slot', async () => {
    const { spies, surface } = renderLayer({ apply: true, scroller: true });
    lift(surface('A'), A_CENTER, A_LIFTED);
    const pointer = { x: 1000, y: 460 }; // B's right half, near its bottom edge
    mouseMove(pointer);
    expect(spies.onReorder).toHaveBeenLastCalledWith('panel', ['B', 'A', 'C']);

    // Now [B | A] / [C]. Scrolling 120 px brings C's lower half (midline 561 → 441) under
    // the pointer, which has not moved since the last reorder.
    const scroller = screen.getByTestId('scroller');
    Object.defineProperty(scroller, 'scrollTop', { configurable: true, writable: true, value: 120 });
    // As in a browser, every box is now 120 px higher in the viewport (dnd-kit's measured
    // rects follow the scroll offset, so the layer sees no drift).
    geometryShiftY = -120;
    stub.setAll(layoutRects({ kpi: INITIAL.kpi, panel: ['B', 'A', 'C'] }, HALVES));
    act(() => {
      scroller.dispatchEvent(new Event('scroll'));
    });
    expect(spies.onReorder).toHaveBeenCalledTimes(2);
    expect(spies.onReorder).toHaveBeenLastCalledWith('panel', ['B', 'C', 'A']);
    await drop(pointer);
  });

  it('enabled=false starts nothing; enabling again restores dragging', async () => {
    const { spies, surface, moveButton, rerender } = renderLayer({ enabled: false });
    lift(surface('A'), A_CENTER, A_LIFTED);
    mouseMove(B_RIGHT);
    mouseUp(B_RIGHT);
    lift(moveButton('A'), A_CENTER, A_LIFTED);
    mouseUp(A_LIFTED);
    expect(spies.onDragStart).not.toHaveBeenCalled();
    expect(spies.onReorder).not.toHaveBeenCalled();

    rerender({ enabled: true });
    lift(surface('A'), A_CENTER, A_LIFTED);
    expect(spies.onDragStart).toHaveBeenCalledWith('panel', 'A');
    await drop(A_LIFTED);
  });

  it('touch: a move past 8 px before the 250 ms long-press scrolls instead; a hold with jitter lifts', async () => {
    installFakeTimers();
    const vibrate = jest.fn<boolean, [VibratePattern]>(() => true);
    Object.defineProperty(navigator, 'vibrate', { configurable: true, writable: true, value: vibrate });
    try {
      const { spies, surface } = renderLayer({ apply: true });

      // dnd-kit cancels a pending press only strictly PAST the tolerance: 9 px here, 8 px in
      // the hold below. The pair pins the tolerance at 8 from both sides.
      touchStart(surface('A'), A_CENTER);
      act(() => {
        jest.advanceTimersByTime(249);
      });
      touchMove(surface('A'), { x: A_CENTER.x + 9, y: A_CENTER.y }); // past the 8 px tolerance
      act(() => {
        jest.advanceTimersByTime(50);
      });
      touchEnd(surface('A'), { x: A_CENTER.x + 9, y: A_CENTER.y });
      expect(spies.onDragStart).not.toHaveBeenCalled();
      expect(spies.onDragCancel).not.toHaveBeenCalled();
      expect(vibrate).not.toHaveBeenCalled();

      // A real finger is never still: drifting 8 px during the hold keeps the long press alive.
      touchStart(surface('A'), A_CENTER);
      act(() => {
        jest.advanceTimersByTime(100);
      });
      touchMove(surface('A'), { x: A_CENTER.x + 8, y: A_CENTER.y });
      act(() => {
        jest.advanceTimersByTime(149);
      });
      expect(spies.onDragStart).not.toHaveBeenCalled();
      act(() => {
        jest.advanceTimersByTime(1);
      });
      expect(spies.onDragStart).toHaveBeenCalledWith('panel', 'A');
      expect(vibrate).toHaveBeenCalledWith(10);

      touchMove(surface('A'), B_RIGHT);
      expect(spies.onReorder).toHaveBeenLastCalledWith('panel', ['B', 'A', 'C']);
      touchEnd(surface('A'), B_RIGHT);
      await settleOverlay();
      expect(spies.onDragEnd).toHaveBeenCalledWith('panel', 'A');
    } finally {
      Reflect.deleteProperty(navigator, 'vibrate');
    }
  });

  it('follows the pointer through two reorders and back into a row-end hole', async () => {
    const { spies, surface } = renderLayer({ apply: true });
    lift(surface('A'), A_CENTER, A_LIFTED);

    mouseMove(B_RIGHT); // [B, A, C]
    mouseMove(C_LOWER); // [B, C, A]
    expect(spies.onReorder).toHaveBeenCalledTimes(2);
    expect(spies.onReorder).toHaveBeenLastCalledWith('panel', ['B', 'C', 'A']);

    // [B | hole] / [C] / [A]: the hole right of B means "after B".
    mouseMove(B_RIGHT);
    expect(spies.onReorder).toHaveBeenCalledTimes(3);
    expect(spies.onReorder).toHaveBeenLastCalledWith('panel', ['B', 'A', 'C']);
    await drop(B_RIGHT);
    expect(spies.onDragEnd).toHaveBeenCalledTimes(1);
  });

  it('re-measures when content shifts the zone mid-drag, then reorders on the fresh rects', async () => {
    const { spies, surface } = renderLayer({ apply: true });
    lift(surface('A'), A_CENTER, A_LIFTED);

    // A banner appears above both zones: every box moves down 64 px. Nothing resizes and the
    // layout key is unchanged, so neither dnd-kit nor the layout-commit re-measure sees it.
    geometryShiftY = 64;
    stub.setAll(layoutRects(INITIAL, HALVES));

    // 14 px into C's upper half on the SHIFTED layout (C is now y 550–700, midline 625). On
    // the stale rects (C at 486–636, midline 561) the same point reads as C's lower half.
    mouseMove({ x: 600, y: 564 }); // drift: re-measured, no reorder from stale rects
    expect(spies.onReorder).not.toHaveBeenCalled();
    mouseMove({ x: 602, y: 566 });
    expect(spies.onReorder).toHaveBeenCalledTimes(1);
    expect(spies.onReorder).toHaveBeenLastCalledWith('panel', ['B', 'A', 'C']);
    await drop({ x: 602, y: 566 });
    expect(spies.onDragEnd).toHaveBeenCalledWith('panel', 'A');
  });

  describe('a release that lands before dnd-kit commits its start', () => {
    // Native events OUTSIDE act, with only microtask checkpoints between them, as a browser
    // delivers a queued release before React's (task-scheduled) DragStart render.
    let wasActEnvironment: unknown;
    beforeEach(() => {
      wasActEnvironment = Reflect.get(globalThis, 'IS_REACT_ACT_ENVIRONMENT');
      Reflect.set(globalThis, 'IS_REACT_ACT_ENVIRONMENT', false);
    });
    afterEach(() => {
      Reflect.set(globalThis, 'IS_REACT_ACT_ENVIRONMENT', wasActEnvironment);
    });

    const native = (type: 'mousedown' | 'mousemove' | 'mouseup', target: EventTarget, at: Point) => {
      target.dispatchEvent(
        new MouseEvent(type, {
          bubbles: true,
          cancelable: true,
          button: 0,
          buttons: type === 'mouseup' ? 0 : 1,
          clientX: at.x,
          clientY: at.y,
        })
      );
    };
    const microtasks = async () => {
      await Promise.resolve();
      await Promise.resolve();
    };
    const settleTasks = () => new Promise(resolve => setTimeout(resolve, 30));

    it('is reported as a cancel, and the layer is idle again', async () => {
      const { spies, surface } = renderLayer({ apply: true });
      native('mousedown', surface('A'), A_CENTER);
      await microtasks();
      native('mousemove', document, A_LIFTED);
      expect(spies.onDragStart).toHaveBeenCalledWith('panel', 'A');
      await microtasks();
      native('mouseup', document, A_LIFTED);
      await settleTasks();

      expect(spies.onDragEnd).not.toHaveBeenCalled();
      expect(spies.onDragCancel).toHaveBeenCalledTimes(1);
      expect(spies.onDragCancel).toHaveBeenCalledWith('panel', 'A');
      expect(document.querySelector('[data-drag-ghost]')).toBeNull();
      // Idle: a same-breakpoint resize is no longer swallowed by the drag guard.
      const pageListener = jest.fn();
      window.addEventListener('resize', pageListener);
      try {
        window.dispatchEvent(new Event('resize'));
        expect(pageListener).toHaveBeenCalledTimes(1);
      } finally {
        window.removeEventListener('resize', pageListener);
      }
    });

    it('a normal drag (the start committed first) still ends once, as a drop', async () => {
      const { spies, surface } = renderLayer({ apply: true });
      native('mousedown', surface('A'), A_CENTER);
      await microtasks();
      native('mousemove', document, A_LIFTED);
      await settleTasks();
      native('mouseup', document, A_LIFTED);
      await settleTasks();
      expect(spies.onDragEnd).toHaveBeenCalledTimes(1);
      expect(spies.onDragCancel).not.toHaveBeenCalled();
    });
  });

  it('keeps dnd-kit silent and its attributes off the page', async () => {
    const { spies, surface, container } = renderLayer({ apply: true });
    lift(surface('A'), A_CENTER, A_LIFTED);
    mouseMove(B_RIGHT);
    expect(spies.onReorder).toHaveBeenCalled();

    const liveRegion = document.querySelector('[id^="DndLiveRegion"]');
    const instructions = document.querySelector('[id^="DndDescribedBy"]');
    expect(liveRegion).not.toBeNull();
    expect(liveRegion?.textContent).toBe('');
    expect(instructions?.textContent).toBe('');
    expect(document.querySelector('[aria-roledescription]')).toBeNull();
    expect(container.querySelector('[role="button"]')).toBeNull();
    expect(container.querySelector('[aria-describedby]')).toBeNull();
    expect(container.querySelector('[aria-pressed]')).toBeNull();

    await drop(B_RIGHT);
    expect(liveRegion?.textContent).toBe('');
  });

  it('portals an aria-hidden ghost at z-index 55, sized and anchored to the grab point', async () => {
    const { surface, container } = renderLayer();
    lift(surface('A'), A_CENTER, A_LIFTED);

    const ghost = document.querySelector<HTMLElement>('[data-drag-ghost]');
    expect(ghost).not.toBeNull();
    if (!ghost) return;
    expect(container.contains(ghost)).toBe(false);
    expect(ghost).toHaveAttribute('aria-hidden', 'true');
    expect(ghost).toHaveTextContent('Work Center Status');
    expect(ghost).toHaveTextContent('Half');
    // A is 592 × 200, grabbed at (296, 100) inside it: the width is capped at 480 and the
    // ghost shifts left so the pointer keeps its relative spot (296 × (1 − 480/592) = 56).
    expect(ghost.style.width).toBe('480px');
    expect(ghost.style.height).toBe('200px');
    expect(parseFloat(ghost.style.left)).toBeCloseTo(56, 6);
    expect(ghost.style.top).toBe('0px');

    const wrapper = ghost.parentElement;
    expect(wrapper?.parentElement).toBe(document.body);
    expect(wrapper?.style.zIndex).toBe(String(DRAG_OVERLAY_Z_INDEX));
    expect(wrapper?.style.pointerEvents).toBe('none');
    expect(wrapper?.style.position).toBe('fixed');

    await drop(A_LIFTED);
    expect(document.querySelector('[data-drag-ghost]')).toBeNull();
  });

  it('drops with a glide-and-fade animation of the overlay', () => {
    animate = installFakeAnimate();
    giveOverlayATransformMatrix();

    const { surface } = renderLayer({ reducedMotion: false });
    lift(surface('A'), A_CENTER, A_LIFTED);
    const wrapper = document.querySelector('[data-drag-ghost]')?.parentElement ?? null;
    expect(wrapper).not.toBeNull();
    mouseUp(A_LIFTED);

    const overlayCalls = animate.calls.filter(call => call.element === wrapper);
    expect(overlayCalls).toHaveLength(1);
    // A sits at (0, 270): the overlay glides from its matrix (40, 50) onto the slot.
    expect(overlayCalls[0].keyframes).toEqual([
      { opacity: 1, transform: 'translate3d(40px, 50px, 0) scaleX(1) scaleY(1)' },
      { opacity: 0, transform: 'translate3d(40px, 320px, 0) scaleX(1) scaleY(1)' },
    ]);
    expect(overlayCalls[0].options).toEqual({
      duration: DROP_ANIMATION_MS,
      easing: DROP_ANIMATION_EASING,
      fill: 'forwards',
    });
  });

  it('runs no drop animation under reduced motion', async () => {
    animate = installFakeAnimate();
    giveOverlayATransformMatrix();

    const { surface } = renderLayer({ reducedMotion: true });
    lift(surface('A'), A_CENTER, A_LIFTED);
    await drop(A_LIFTED);
    expect(animate.calls).toHaveLength(0);
    expect(document.querySelector('[data-drag-ghost]')).toBeNull();
  });

  it('is the default export the lazy loader resolves', async () => {
    await expect(loadDashboardDragLayer()).resolves.toBe(DashboardDragLayer);
  });

  it('never calls the page back once unmounted mid-drag', () => {
    const { spies, surface, rerender } = renderLayer({ apply: true });
    lift(surface('A'), A_CENTER, A_LIFTED);
    expect(spies.onDragStart).toHaveBeenCalledTimes(1);

    rerender({ layer: false });
    mouseMove(B_RIGHT);
    mouseUp(B_RIGHT);
    expect(spies.onReorder).not.toHaveBeenCalled();
    expect(spies.onDragEnd).not.toHaveBeenCalled();
    expect(spies.onDragCancel).not.toHaveBeenCalled();
  });

  it('the REAL WidgetCell lifts through its surface and its Move button, with no dnd-kit attributes on it', async () => {
    const definition = WIDGETS_BY_ID.get('kpi.overdue')!;
    const Tile: DashboardWidgetComponent = function Tile() {
      return <div>Overdue tile</div>;
    };
    const editor: WidgetCellEditor = {
      controlsDisabled: false,
      menuFor: null,
      dragging: null,
      highlightId: null,
      moveBy: jest.fn(),
      moveTo: jest.fn(),
      remove: jest.fn(),
      openMenu: jest.fn(),
      closeMenu: jest.fn(),
      setPanelSize: jest.fn(),
    };
    const bridge = createDragBridge();
    const spies = createSpies();
    stub.set('kpi.overdue', { left: 0, top: KPI_TOP, width: 233.6, height: 72 });
    stub.set('zone-kpi', { left: 0, top: KPI_TOP, width: GRID_WIDTH, height: 72 });
    const { container } = render(
      <MemoryRouter>
        <div data-testid="zone-kpi" ref={bridge.zoneRef('kpi')}>
          <WidgetCell
            definition={definition}
            component={Tile}
            zone="kpi"
            edit={{ editor, bridge, index: 0, count: 1 }}
          />
        </div>
        <DashboardDragLayer
          bridge={bridge}
          enabled
          orders={{ kpi: ['kpi.overdue'], panel: [] }}
          layoutKey="one"
          reducedMotion
          describe={describeWidget}
          onDragStart={spies.onDragStart}
          onReorder={spies.onReorder}
          onDragEnd={spies.onDragEnd}
          onDragCancel={spies.onDragCancel}
        />
      </MemoryRouter>
    );
    const surface = container.querySelector('[data-drag-surface]')!;
    lift(surface, K1_CENTER, K1_LIFTED);
    expect(spies.onDragStart).toHaveBeenCalledWith('kpi', 'kpi.overdue');
    await drop(K1_LIFTED);
    await act(async () => {
      await new Promise(resolve => setTimeout(resolve, 60));
    });
    lift(screen.getByRole('button', { name: 'Move Overdue' }), K1_CENTER, K1_LIFTED);
    expect(spies.onDragStart).toHaveBeenCalledTimes(2);

    // dnd-kit's `attributes` (role=button, tabindex=0, aria-roledescription, aria-pressed and
    // its DndDescribedBy instructions) never reach the page's cell.
    expect(document.querySelector('[aria-roledescription]')).toBeNull();
    expect(container.querySelector('[role="button"]')).toBeNull();
    expect(container.querySelector('[tabindex="0"]')).toBeNull();
    expect(container.querySelector('[aria-pressed]')).toBeNull();
    expect(container.querySelector('[aria-describedby*="DndDescribedBy"]')).toBeNull();
    await drop(K1_LIFTED);
  });
});
